hitArea.css:
/* Tıklanabilir alan = görünen alan × 1.12 (HIT_RULES R1–R10)
   --hit-t/r/b/l değerlerini HitArea motoru yazar: ideal olarak her kenar boyutun %6’i,
   komşu kontrole göre boşluk/2 ile sınırlı. Görünen kutu ve yerleşim değişmez. */
.hit { position: relative; }
.hit::after {
  content: "";
  position: absolute;
  top: calc(var(--hit-t, 0px) * -1);
  right: calc(var(--hit-r, 0px) * -1);
  bottom: calc(var(--hit-b, 0px) * -1);
  left: calc(var(--hit-l, 0px) * -1);
}

/* JS yoksa yedek: yalnızca R1 + R2 (komşu kuralı yok).
   top/bottom yüzdesi yüksekliğe, left/right yüzdesi genişliğe göre hesaplanır. */
.hit-fallback { position: relative; }
.hit-fallback::after { content: ""; position: absolute; inset: -6%; }

/* R9: Input için görünmez suffix (affix sarmalayıcıyı zorlar) */
.ant-input-suffix:has(> .hit-sfx) { display: none; }

